SELECT id, name, location_name AS locationName, longitude, latitude, max_vehicles AS maxVehicles, current_vehicles AS currentVehicles, image, price FROM private_charge_station WHERE is_deleted = 0
AND (name LIKE CONCAT('%', #{keyword}, '%') OR location_name LIKE CONCAT('%', #{keyword}, '%'))
AND longitude BETWEEN #{minLng} AND #{maxLng}
AND latitude BETWEEN #{minLat} AND #{maxLat}
